import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

elementwise_relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val > 0 ? val : 0;
    }
}

torch::Tensor elementwise_relu_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    elementwise_relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

elementwise_relu_cpp_source = "torch::Tensor elementwise_relu_cuda(torch::Tensor input);"

elementwise_relu = load_inline(
    name="elementwise_relu",
    cpp_sources=elementwise_relu_cpp_source,
    cuda_sources=elementwise_relu_source,
    functions=["elementwise_relu_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, 
            out_channels, 
            kernel_size, 
            stride=stride, 
            padding=padding, 
            output_padding=output_padding, 
            groups=groups, 
            bias=bias
        )
        self.elementwise_relu = elementwise_relu

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = self.conv_transpose3d(x)
        out = self.elementwise_relu.elementwise_relu_cuda(out)
        return out
